css:
.premtrap-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a3142;
    background: linear-gradient(180deg, #f4f1ea 0%, #ece7db 100%);
    border-radius: 16px;
}

.premtrap-container * {
    box-sizing: border-box;
}

.premtrap-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #11192b 0%, #1c2942 55%, #2a3a5c 100%);
    color: #f6f2e7;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #c8a24a;
    box-shadow: 0 14px 36px rgba(17, 25, 43, 0.32);
}

.premtrap-header h1 {
    margin: 10px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.4rem;
    font-weight: 700;
    letter-spacing: 0.3px;
    color: #e7c573;
}

.premtrap-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #e7c573;
    background: rgba(231, 197, 115, 0.12);
    border: 1px solid rgba(231, 197, 115, 0.40);
    padding: 5px 14px;
    border-radius: 4px;
}

.premtrap-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6ddea;
}

.premtrap-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #4a546a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.premtrap-period-counter #currentDay,
.premtrap-period-counter #maxPeriods {
    font-weight: 800;
    color: #1c2942;
}

.premtrap-round-name {
    background: #1c2942;
    color: #e7c573;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.4px;
    margin-left: 4px;
}

.premtrap-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #9a2b2b;
    background: rgba(154, 43, 43, 0.10);
    border: 1px solid rgba(154, 43, 43, 0.32);
    padding: 4px 12px;
    border-radius: 4px;
}

.premtrap-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.premtrap-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #ded6c3;
    box-shadow: 0 6px 16px rgba(17, 25, 43, 0.08);
    border-top: 4px solid #1c2942;
}

.premtrap-card-return { border-top-color: #2f8f6b; }
.premtrap-card-premium { border-top-color: #c8a24a; }
.premtrap-card-synergy { border-top-color: #3a6ea5; }
.premtrap-card-bias { border-top-color: #9a2b2b; }

.premtrap-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a8090;
}

.premtrap-value {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.5rem;
    font-weight: 700;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1c2942;
    font-variant-numeric: tabular-nums;
}

.premtrap-card-return .premtrap-value { color: #2f8f6b; }
.premtrap-card-premium .premtrap-value { color: #a8842f; }
.premtrap-card-synergy .premtrap-value { color: #3a6ea5; }
.premtrap-card-bias .premtrap-value { color: #9a2b2b; }

.premtrap-sublabel {
    font-size: 0.75rem;
    color: #8b8f9c;
    line-height: 1.35;
}

.premtrap-return-negative .premtrap-value { color: #c0392b; }
.premtrap-return-positive .premtrap-value { color: #2f8f6b; }

.premtrap-bias-high { border-top-color: #c0392b; }
.premtrap-bias-high .premtrap-value { color: #c0392b; }
.premtrap-bias-low { border-top-color: #2f8f6b; }
.premtrap-bias-low .premtrap-value { color: #2f8f6b; }

.premtrap-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1c2942;
    border: 1px solid #c8a24a;
    color: #e8ecf3;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.premtrap-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c573;
}

.premtrap-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c8a24a;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(17, 25, 43, 0.07);
}

.premtrap-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.premtrap-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 700;
    font-size: 1.1rem;
    color: #1c2942;
    margin-bottom: 6px;
}

.premtrap-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4254;
}

.premtrap-briefing-text strong { color: #a8842f; }
.premtrap-briefing-text em { color: #9a2b2b; font-style: italic; }

.premtrap-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ded6c3;
    box-shadow: 0 6px 16px rgba(17, 25, 43, 0.07);
}

.premtrap-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.15rem;
    font-weight: 700;
    color: #1c2942;
    border-bottom: 2px solid #e7dcc2;
    padding-bottom: 8px;
}

.premtrap-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3142;
    margin: 14px 0 6px;
}

.premtrap-container select,
.premtrap-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9c0aa;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #fbf9f3;
    color: #1c2942;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.premtrap-container select:focus,
.premtrap-container input[type="number"]:focus {
    outline: none;
    border-color: #c8a24a;
    box-shadow: 0 0 0 3px rgba(200, 162, 74, 0.22);
}

.premtrap-container select option {
    background-color: #fbf9f3;
    color: #1c2942;
}

.premtrap-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c8a24a;
}

.premtrap-range-readout,
.premtrap-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a546a;
    margin-top: 4px;
}

.premtrap-range-readout span:nth-child(2),
.premtrap-alloc-readout span:nth-child(2) {
    color: #a8842f;
    font-weight: 800;
}

.premtrap-bid-eq {
    color: #1c2942;
    font-weight: 700;
    margin-left: 6px;
}

.premtrap-hint {
    font-size: 0.8rem;
    color: #8b8f9c;
    margin-top: 4px;
    line-height: 1.4;
}

.premtrap-safeguard-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.premtrap-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #fbf9f3;
    border: 1px solid #ddd3bb;
    border-radius: 7px;
    padding: 10px 12px;
    margin: 0;
    font-weight: 600;
    font-size: 0.89rem;
    color: #2a3142;
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
}

.premtrap-check:hover {
    border-color: #c8a24a;
    background: #fdf8ec;
}

.premtrap-check input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 1px;
    flex: 0 0 18px;
    accent-color: #1c2942;
}

.premtrap-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.premtrap-container .btn-primary {
    background: linear-gradient(135deg, #1c2942 0%, #2a3a5c 100%);
    border: 1px solid #c8a24a;
    color: #e7c573;
    padding: 11px 28px;
    border-radius: 7px;
    box-shadow: 0 8px 20px rgba(17, 25, 43, 0.28);
    letter-spacing: 0.3px;
}

.premtrap-container .btn-primary:hover {
    filter: brightness(1.12);
    color: #f4dca0;
}

.premtrap-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9c0aa;
    color: #6a7080;
    background: transparent;
}

.premtrap-coach {
    background: linear-gradient(135deg, #11192b 0%, #1f2c46 100%);
    color: #dde3ee;
    border: 1px solid #c8a24a;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 25, 43, 0.22);
}

.premtrap-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c573;
    margin-bottom: 8px;
}

.premtrap-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.premtrap-coach-body strong { color: #e7c573; }
.premtrap-coach-body em { color: #f0b8b8; font-style: italic; }

.premtrap-history,
.premtrap-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ded6c3;
    box-shadow: 0 6px 16px rgba(17, 25, 43, 0.07);
}

.premtrap-history h3,
.premtrap-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1c2942;
}

.premtrap-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3142;
}

.premtrap-container table#usfHistoryTable th {
    background: #1c2942;
    color: #e7c573;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #c8a24a;
}

.premtrap-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e9e2d2;
    color: #3a4254;
}

.premtrap-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.premtrap-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .premtrap-container {
        padding: 14px;
    }
    .premtrap-header h1 {
        font-size: 1.8rem;
    }
    .premtrap-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .premtrap-value {
        font-size: 2rem;
    }
    .premtrap-clock {
        margin-left: 0;
    }
    .premtrap-period-counter {
        font-size: 0.86rem;
    }
    .premtrap-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .premtrap-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* === premtrap-cm: completion debrief (appended, adapter 1.1.0) === */
.premtrap-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.premtrap-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.premtrap-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.premtrap-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.premtrap-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.premtrap-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.premtrap-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.premtrap-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.premtrap-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.premtrap-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.premtrap-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.premtrap-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.premtrap-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.premtrap-cm-insights { margin: 0; padding-left: 20px; }
.premtrap-cm-insights li { margin: 5px 0; line-height: 1.4; }

