(function() {
    'use strict';

    class PremiumTrapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Premium Trap`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // --- Numbers reference card (Rheinwerk / Voltura) ---
            this.STANDALONE = 1000;          // Voltura standalone EV, EUR M (12.5x EBITDA 80)
            this.SYN_LOW = 45;               // synergy band, EUR M run-rate
            this.SYN_BASE = 90;
            this.SYN_BULL = 130;
            this.SYN_BREAKEVEN = 120;        // recurring synergies needed to break even on the premium
            this.PV_FACTOR = 6.0;            // capitalisation multiple at 12% WACC (PV ≈ run-rate / 0.12 ≈ ×8, haircut to ×6 for ramp/tax)
            this.SHARES = 91;                // Rheinwerk shares outstanding, M (illustrative; ~EUR 0.06/share per EUR 100M premium if synergies miss)
            this.GOV_BUDGET = 9;             // governance days available before the 21-day deadline
            this.RIVAL_PREMIUM = 35;         // US major's opening premium, %
            this.BANKER_SIGNAL = 55;         // "wins it" escalation cue, %

            // Concept truths.
            this.TRUE_ANCHOR = `standalone`;
            this.TRUE_SYNERGY = `weighted`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    bias: 70,                // decision-bias score, 0-100, LOWER better
                    acqReturn: 0,            // realised value created per share, EUR (set in R4)
                    premiumPct: null,        // bid premium over standalone, % (set in R3)
                    synergyCapture: null,    // realised synergies / base case, % (set in R4)
                    governanceDays: 0,       // days of the governance budget spent
                    rigor: 0,                // 0-1, how much procedural rationality was installed
                    synergyEstimate: 90,     // EUR M the team capitalises (tightened by R1/R2)
                    walkAwaySet: false,      // a ratified walk-away price exists
                    championSeparated: false,// decision hygiene installed
                    dealWon: null,           // true/false after R3
                    overpaid: false,         // premium above break-even line
                    biasHistory: [70],
                    captureHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately ANCHORED / overconfident mix —
                // a blind click-through reproduces the classic errors and must NOT auto-win.
                state.decisions = {
                    anchor: `standalone`,
                    synergyTreat: `weighted`,
                    biasFlags: 1,
                    sgOutside: false,
                    sgPremortem: false,
                    sgWalkaway: false,
                    sgRedteam: false,
                    sgHygiene: false,
                    friction: `trim`,
                    premium: 50,
                    discipline: `stretch`,
                    structure: `some`,
                    integration: `standard`,
                    board: `optimistic`,
                    humility: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const an = document.getElementById(`anchorInput`);
                const sy = document.getElementById(`synergyTreatInput`);
                const bf = document.getElementById(`biasFlagInput`);
                if (an) decisions.anchor = an.value;
                if (sy) decisions.synergyTreat = sy.value;
                if (bf) decisions.biasFlags = parseInt(bf.value, 10);
                if (!Number.isFinite(decisions.biasFlags) || decisions.biasFlags < 0 || decisions.biasFlags > 5) {
                    warn(`warn_bias_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`sgOutside`, `sgPremortem`, `sgWalkaway`, `sgRedteam`, `sgHygiene`];
                ids.forEach((id) => {
                    const el = document.getElementById(id + `Input`);
                    if (el) decisions[id] = !!el.checked;
                });
                const fr = document.getElementById(`frictionInput`);
                if (fr) decisions.friction = fr.value;
                const days = this._safeguardDays(decisions);
                if (days > this.GOV_BUDGET) {
                    warn(`warn_days_over`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`premiumInput`);
                const di = document.getElementById(`disciplineInput`);
                const st = document.getElementById(`structureInput`);
                if (pr) decisions.premium = parseInt(pr.value, 10);
                if (di) decisions.discipline = di.value;
                if (st) decisions.structure = st.value;
                if (!Number.isFinite(decisions.premium) || decisions.premium < 0 || decisions.premium > 70) {
                    warn(`warn_premium_range`); return false;
                }
            } else if (round === 4) {
                const ig = document.getElementById(`integrationInput`);
                const bo = document.getElementById(`boardInput`);
                const hu = document.getElementById(`humilityInput`);
                if (ig) decisions.integration = ig.value;
                if (bo) decisions.board = bo.value;
                if (hu) decisions.humility = parseInt(hu.value, 10);
                if (!Number.isFinite(decisions.humility) || decisions.humility < 0 || decisions.humility > 100) {
                    warn(`warn_humility_range`); return false;
                }
            }
            return true;
        }

        _safeguardDays(d) {
            return (d.sgOutside ? 2 : 0) + (d.sgPremortem ? 1 : 0) + (d.sgWalkaway ? 1 : 0) +
                   (d.sgRedteam ? 2 : 0) + (d.sgHygiene ? 3 : 0);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let biasDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: build up from standalone vs anchor to the ask (Common Error 1),
                // probability-weight the synergy band vs capitalise base/bull in full (Common Error 2).
                switch (d.anchor) {
                    case `standalone`: biasDelta -= 18; coachKey = `coach_r1_standalone`; break;
                    case `median`: biasDelta -= 6; coachKey = `coach_r1_median`; break;
                    case `ask`: biasDelta += 10; coachKey = `coach_r1_ask`; break;
                }
                switch (d.synergyTreat) {
                    case `weighted`: biasDelta -= 12; ds.synergyEstimate = 75; break;
                    case `base`: biasDelta += 4; ds.synergyEstimate = 90; if (coachKey === `coach_default`) coachKey = `coach_r1_base`; break;
                    case `bull`: biasDelta += 12; ds.synergyEstimate = 130; coachKey = `coach_r1_bull`; break;
                }
                // Each CEO-memo claim correctly tagged as bias is a debiasing act.
                biasDelta -= d.biasFlags * 3;
                if (d.biasFlags <= 1) { biasDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r1_lowflags`; }

                if (d.anchor === `standalone` && d.synergyTreat === `weighted`) coachKey = `coach_r1_sharp`;
                summaryKey = (d.anchor === `standalone` && d.synergyTreat === `weighted`) ? `sum_r1_good` :
                             (d.anchor === `ask` || d.synergyTreat === `bull` ? `sum_r1_anchored` : `sum_r1_weak`);
            } else if (round === 2) {
                // Install procedural rationality BEFORE bidding (Common Errors 3 & 5).
                const days = this._safeguardDays(d);
                ds.governanceDays = days;

                let rigor = 0;
                if (d.sgOutside) { biasDelta -= 8; rigor += 0.22; }       // outside view tightens the estimate toward base
                if (d.sgPremortem) { biasDelta -= 7; rigor += 0.16; }
                if (d.sgWalkaway) { biasDelta -= 9; rigor += 0.18; ds.walkAwaySet = true; }
                if (d.sgRedteam) { biasDelta -= 7; rigor += 0.16; }
                if (d.sgHygiene) { biasDelta -= 6; rigor += 0.14; ds.championSeparated = true; }
                ds.rigor = Math.min(1, Math.round(rigor * 100) / 100);

                // The outside view / red team pull a bull estimate back toward the credible run-rate.
                if ((d.sgOutside || d.sgRedteam) && ds.synergyEstimate > 90) ds.synergyEstimate = 90;

                if (days === 0) {
                    biasDelta += 12; coachKey = `coach_r2_none`;
                } else if (d.friction === `defend` && ds.walkAwaySet && ds.championSeparated) {
                    coachKey = `coach_r2_full`;
                } else if (d.sgWalkaway && d.sgHygiene) {
                    coachKey = `coach_r2_strong`;
                } else {
                    coachKey = `coach_r2_partial`;
                }

                // Handling Brandt's friction: defending the process is itself debiasing;
                // skipping to avoid antagonising the CEO leaves bias on the table.
                switch (d.friction) {
                    case `defend`: biasDelta -= 5; break;
                    case `trim`: biasDelta += 2; break;
                    case `skip`: biasDelta += 8; if (days <= 1) coachKey = `coach_r2_none`; break;
                }

                summaryKey = (days >= 4 && ds.walkAwaySet && ds.championSeparated) ? `sum_r2_good` :
                             (days === 0 ? `sum_r2_none` : `sum_r2_partial`);
            } else if (round === 3) {
                // Set the bid premium under auction pressure (Common Error 4: winner's curse).
                let prem = d.premium;

                // Discipline: honouring a pre-committed walk-away caps escalation; overriding it
                // (champion beats approver, Common Error 5) pushes the number up under pressure.
                if (d.discipline === `chase`) {
                    prem = Math.max(prem, this.BANKER_SIGNAL);   // chasing the rival clears 55%+
                    biasDelta += 12;
                    if (!ds.championSeparated) prem = Math.max(prem, 55);
                } else if (d.discipline === `stretch`) {
                    prem = Math.max(prem, this.RIVAL_PREMIUM + 5);
                    biasDelta += 4;
                } else { // honor
                    biasDelta -= 6;
                    if (!ds.walkAwaySet) { biasDelta += 6; coachKey = `coach_r3_nowalkaway`; }
                }
                prem = Math.max(0, Math.min(70, prem));
                ds.premiumPct = prem;

                // Did we win the asset? Below the rival's opening premium we lose Voltura.
                const won = prem >= this.RIVAL_PREMIUM;
                ds.dealWon = won;

                // Break-even: each 10% premium ≈ EUR 100M; break-even needs ≈ EUR 120M synergies.
                // Implied synergies required = premium(EUR M) / PV_FACTOR.
                const premiumEur = prem * 10;                       // EUR M of premium paid
                const synergiesRequired = premiumEur / this.PV_FACTOR;
                ds.overpaid = (synergiesRequired > this.SYN_BREAKEVEN) || (prem > 12 && synergiesRequired > ds.synergyEstimate);

                if (!won) {
                    biasDelta -= 2; coachKey = `coach_r3_lost`;
                } else if (prem >= this.BANKER_SIGNAL) {
                    biasDelta += 8; coachKey = (d.discipline === `chase`) ? `coach_r3_winnerscurse` : `coach_r3_high`;
                } else if (prem <= this.RIVAL_PREMIUM + 5) {
                    biasDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_disciplined`;
                } else if (coachKey === `coach_default`) {
                    coachKey = `coach_r3_mid`;
                }

                // Structure hedges synergy risk and adds rigor toward realisation.
                switch (d.structure) {
                    case `hedged`: biasDelta -= 6; ds.rigor = Math.min(1, ds.rigor + 0.12); break;
                    case `some`: biasDelta -= 2; ds.rigor = Math.min(1, ds.rigor + 0.05); break;
                    case `cash`: biasDelta += 5; if (coachKey === `coach_default` || coachKey === `coach_r3_mid`) coachKey = `coach_r3_allcash`; break;
                }

                summaryKey = !won ? `sum_r3_lost` :
                             (prem >= this.BANKER_SIGNAL ? `sum_r3_curse` :
                             (prem <= this.RIVAL_PREMIUM + 5 && d.discipline === `honor` ? `sum_r3_good` : `sum_r3_mid`));
            } else if (round === 4) {
                // Recover: synergies land partly as a function of imposed rigor (Pavićević finding).
                // Integration intensity and the board narrative shape realised capture and bias.
                let captureBase;
                switch (d.integration) {
                    case `disciplined`: captureBase = 0.55; break;
                    case `standard`: captureBase = 0.42; break;
                    case `rushed`: captureBase = 0.30; biasDelta += 6; break;
                    default: captureBase = 0.40;
                }
                // Rigor installed earlier raises the realised band; over-promising rushes the ramp.
                let capturePct = captureBase + ds.rigor * 0.40;     // 0..~0.95
                if (d.integration === `rushed`) capturePct -= 0.05;
                capturePct = Math.max(0.12, Math.min(0.98, capturePct));
                ds.synergyCapture = Math.round(capturePct * 100);

                // Realised synergies (EUR M) = capture * base case run-rate.
                const realisedSyn = capturePct * this.SYN_BASE;
                ds.realisedSynergies = Math.round(realisedSyn);

                // Acquisition return per share: PV of realised synergies minus premium paid,
                // spread over shares. ~EUR 0.06/share lost per EUR 100M premium if synergies miss.
                const prem = ds.premiumPct != null ? ds.premiumPct : 50;
                if (ds.dealWon === false) {
                    // Lost the asset: return is the value NOT destroyed, but the strategic gap is real.
                    ds.acqReturn = 0;
                } else {
                    const premiumEur = prem * 10;                   // EUR M premium paid
                    const synPv = realisedSyn * this.PV_FACTOR;     // EUR M PV of realised synergies
                    ds.acqReturn = Math.round(((synPv - premiumEur) / this.SHARES) * 100) / 100;
                }

                // Board / analyst narrative: honest reconciliation debiases; declaring a "win"
                // when the champion made the public commitment is escalation theatre.
                switch (d.board) {
                    case `honest`: biasDelta -= 8; break;
                    case `optimistic`: biasDelta += 3; break;
                    case `declare`: biasDelta += 9; if (!ds.championSeparated) biasDelta += 4; break;
                }
                if (d.humility >= 60) biasDelta -= 5;
                else if (d.humility <= 25) biasDelta += 5;

                if (ds.dealWon === false) coachKey = `coach_r4_lost`;
                else if (ds.acqReturn > 0 && ds.synergyCapture >= 60 && d.board === `honest`) coachKey = `coach_r4_created`;
                else if (ds.acqReturn < 0 && prem >= this.BANKER_SIGNAL) coachKey = `coach_r4_curse`;
                else if (ds.acqReturn < 0) coachKey = `coach_r4_destroyed`;
                else coachKey = `coach_r4_mixed`;

                summaryKey = ds.dealWon === false ? `sum_r4_lost` :
                             (ds.acqReturn > 0 && ds.synergyCapture >= 60 ? `sum_r4_good` :
                             (ds.acqReturn < 0 ? `sum_r4_destroyed` : `sum_r4_mixed`));
            }

            // Apply the bias delta (clamped 0-100; starts high, debiasing pulls it down).
            ds.bias = Math.max(0, Math.min(100, Math.round(ds.bias + biasDelta)));
            ds.biasHistory.push(ds.bias);
            ds.captureHistory.push(ds.synergyCapture != null ? ds.synergyCapture : 0);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                bias: ds.bias,
                biasDelta: Math.round(biasDelta),
                premiumPct: ds.premiumPct,
                synergyCapture: ds.synergyCapture,
                acqReturn: ds.acqReturn,
                governanceDays: ds.governanceDays,
                rigor: ds.rigor,
                synergyEstimate: ds.synergyEstimate,
                dealWon: ds.dealWon,
                overpaid: ds.overpaid,
                walkAwaySet: ds.walkAwaySet,
                championSeparated: ds.championSeparated,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtEur(v) {
            // EUR per-share, German notation: symbol after, comma decimal — e.g. "0,42 €".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Number(v));
            const num = abs.toFixed(2).replace(`.`, `,`);
            if (lang === `es`) return `${sign}${num} €`;
            return `${sign}${num} €`;
        }

        _fmtEurM(v) {
            // EUR millions, German notation: thousands "." decimal "," — e.g. "1.500 €M".
            const n = Math.round(Number(v));
            const grouped = String(n).replace(/\B(?=(\d{3})+(?!\d))/g, `.`);
            return `${grouped} €M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`returnDisplay`, `domainState.acqReturn`, (v) => {
                const card = document.querySelector(`.premtrap-card-return`);
                if (card) {
                    card.classList.toggle(`premtrap-return-positive`, Number(v) > 0.005);
                    card.classList.toggle(`premtrap-return-negative`, Number(v) < -0.005);
                }
                return self._fmtEur(Number(v));
            });
            uiManager.bind(`premiumDisplay`, `domainState.premiumPct`, (v) => {
                if (v === null || v === undefined) return window.mySimulation.t(`pending_dash`);
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`synergyDisplay`, `domainState.synergyCapture`, (v) => {
                if (v === null || v === undefined) return window.mySimulation.t(`pending_dash`);
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`biasDisplay`, `domainState.bias`, (v) => {
                const card = document.querySelector(`.premtrap-card-bias`);
                if (card) {
                    card.classList.toggle(`premtrap-bias-high`, Number(v) >= 60);
                    card.classList.toggle(`premtrap-bias-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.governanceDays`, (v) => {
                return self._budgetLabel(Number(v));
            });

            // Bias-flag slider readout.
            const bf = document.getElementById(`biasFlagInput`);
            const bfReadout = document.getElementById(`biasFlagReadout`);
            if (bf && bfReadout) {
                bfReadout.textContent = bf.value;
                bf.addEventListener(`input`, function() { bfReadout.textContent = bf.value; });
            }

            // Premium slider readout + live bid equivalent in EUR M.
            const pr = document.getElementById(`premiumInput`);
            const prReadout = document.getElementById(`premiumReadout`);
            const bidEq = document.getElementById(`bidEqDisplay`);
            const updatePrem = function() {
                if (prReadout) prReadout.textContent = pr.value;
                if (bidEq) {
                    const bid = self.STANDALONE * (1 + (parseInt(pr.value, 10) || 0) / 100);
                    bidEq.textContent = `≈ ` + self._fmtEurM(bid);
                }
            };
            if (pr) { updatePrem(); pr.addEventListener(`input`, updatePrem); }

            // Safeguard days live total.
            const sgIds = [`sgOutsideInput`, `sgPremortemInput`, `sgWalkawayInput`, `sgRedteamInput`, `sgHygieneInput`];
            const daysReadout = document.getElementById(`daysReadout`);
            const recompute = function() {
                const map = { sgOutsideInput: 2, sgPremortemInput: 1, sgWalkawayInput: 1, sgRedteamInput: 2, sgHygieneInput: 3 };
                let total = 0;
                sgIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el && el.checked) total += map[id];
                });
                if (daysReadout) daysReadout.textContent = total;
                const bar = document.querySelector(`.premtrap-alloc-readout`);
                if (bar) bar.style.color = (total > self.GOV_BUDGET) ? `#c0392b` : ``;
            };
            sgIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`change`, recompute);
            });
            recompute();
        }

        _budgetLabel(days) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return `${Math.round(days)} / ${this.GOV_BUDGET} ` + t(`days_unit`);
        }

        getChartConfig() {
            return {
                premtrapChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Decision-Bias Score (lower better)`,
