                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7a8090` }, grid: { color: `rgba(28,41,66,0.07)` },
                                title: { display: true, text: `0–100`, color: `#7a8090` }
                            },
                            x: {
                                ticks: { color: `#7a8090` }, grid: { color: `rgba(28,41,66,0.05)` },
                                title: { display: true, text: `Round`, color: `#7a8090` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.biasHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                premtrapChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.biasHistory },
                        { data: ds.captureHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const bias = Math.round(ds.bias);
            const premium = ds.premiumPct != null ? Math.round(ds.premiumPct) : null;
            const capture = ds.synergyCapture != null ? Math.round(ds.synergyCapture) : 0;
            const acqReturn = ds.acqReturn;
            const returnScore = Math.max(-36, Math.min(36, acqReturn * 120));
            const premiumScore = premium == null ? 0 : Math.max(0, 30 - Math.abs(premium - 25));
            return Math.round(
                (returnScore + 36) * 0.34 + (100 - bias) * 0.30 + capture * 0.22 + premiumScore * 0.40
            );
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const bias = Math.round(ds.bias);
            const premium = ds.premiumPct != null ? Math.round(ds.premiumPct) : null;
            const capture = ds.synergyCapture != null ? Math.round(ds.synergyCapture) : 0;
            const acqReturn = ds.acqReturn;
            const won = ds.dealWon === true;

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const valueCreated = won && acqReturn > 0;
            const debiased = bias <= 35;
            const disciplined = premium != null && premium <= 40 && (ds.walkAwaySet || won === false);
            const winnersCurse = won && acqReturn < 0 && premium != null && premium >= this.BANKER_SIGNAL;
            const overcorrected = won === false;

            let performanceKey = `grade_trap`;
            if (valueCreated && debiased && composite >= 75) performanceKey = `grade_creator`;
            else if (valueCreated && capture >= 55) performanceKey = `grade_synergies`;
            else if (winnersCurse) performanceKey = `grade_curse`;
            else if (overcorrected) performanceKey = `grade_overcorrected`;
            else if (acqReturn < 0) performanceKey = `grade_destroyed`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (valueCreated && debiased) insights.push(window.mySimulation.t(`insight_creator`));
            else if (winnersCurse) insights.push(window.mySimulation.t(`insight_curse`));
            else if (overcorrected) insights.push(window.mySimulation.t(`insight_lost`));
            else if (acqReturn < 0) insights.push(window.mySimulation.t(`insight_destroyed`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!ds.walkAwaySet && won) insights.push(window.mySimulation.t(`insight_nowalkaway`));
            if (!ds.championSeparated && bias > 40) insights.push(window.mySimulation.t(`insight_nohygiene`));
            if (ds.governanceDays === 0) insights.push(window.mySimulation.t(`insight_nogovernance`));
            if (capture >= 60 && acqReturn > 0) insights.push(window.mySimulation.t(`insight_capture`));
            if (bias <= 30) insights.push(window.mySimulation.t(`insight_lowbias`));

            return {
                bias: bias,
                premium: premium,
                capture: capture,
                acqReturn: acqReturn,
                won: won,
                valueCreated: valueCreated,
                debiased: debiased,
                disciplined: disciplined,
                winnersCurse: winnersCurse,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: valueCreated,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k, v) => window.mySimulation.t(k, v);
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_trap`);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const badge = (ok, okKey, noKey) => `<span class="premtrap-cm-badge ${ok ? `premtrap-cm-ok` : `premtrap-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="premtrap-cm-kpi"><div class="premtrap-cm-kpi-v">${esc(val)}</div><div class="premtrap-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            const ret = (s.acqReturn != null) ? this._fmtEur(Number(s.acqReturn)) : `\u2014`;
            let badges = badge(s.won === true, `cm_badge_won`, `cm_badge_walked`)
                       + badge(s.valueCreated === true, `cm_badge_value`, `cm_badge_novalue`)
                       + badge(s.debiased === true, `cm_badge_debiased`, `cm_badge_biased`);
            if (s.winnersCurse) badges += `<span class="premtrap-cm-badge premtrap-cm-no">${esc(t(`cm_badge_curse`))}</span>`;
            return `<div class="premtrap-cm">`
                + `<div class="premtrap-cm-head"><div class="premtrap-cm-score">${score}<span class="premtrap-cm-max">/100</span></div>`
                + `<div class="premtrap-cm-grade">${esc(grade)}</div></div>`
                + `<div class="premtrap-cm-badges">${badges}</div>`
                + `<div class="premtrap-cm-kpis">`
                + kpi(t(`cm_kpi_bias`), (s.bias != null ? s.bias : `\u2014`))
                + kpi(t(`cm_kpi_premium`), (s.premium != null ? s.premium + `%` : `\u2014`))
                + kpi(t(`cm_kpi_capture`), (s.capture != null ? s.capture + `%` : `\u2014`))
                + kpi(t(`cm_kpi_return`), ret)
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="premtrap-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.governanceDays === 0 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_governance`);
            if (ds.premiumPct != null && ds.premiumPct >= this.BANKER_SIGNAL) return window.mySimulation.t(`hint_curse`);
            if (ds.dealWon === false) return window.mySimulation.t(`hint_lost`);
            if (ds.bias >= 60) return window.mySimulation.t(`hint_bias`);
            if (!ds.walkAwaySet && state.currentPeriod >= 2 && state.currentPeriod <= 3) return window.mySimulation.t(`hint_walkaway`);
            if (ds.bias <= 30 && ds.synergyCapture != null && ds.synergyCapture >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.bias`, label: `Bias`, i18nKey: `col_bias`, formatter: (v) => Math.round(v) },
                { key: `results.premiumPct`, label: `Premium`, i18nKey: `col_premium`, formatter: (v) => (v == null ? `—` : Math.round(v) + `%`) },
                { key: `results.synergyCapture`, label: `Capture`, i18nKey: `col_capture`, formatter: (v) => (v == null ? `—` : Math.round(v) + `%`) },
                { key: `results.acqReturn`, label: `Return`, i18nKey: `col_return`, formatter: (v) => self._fmtEur(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

